from typing import Optional

from training_data_bot.ai.base import BaseAIProvider


class MockAIProvider(BaseAIProvider):
    """
    A predictable AI provider for development and testing.

    It does not connect to an external AI service.
    """

    async def generate(
        self,
        prompt: str,
        temperature: float = 0.7,
        max_tokens: Optional[int] = None,
    ) -> str:
        if not prompt or not prompt.strip():
            raise ValueError("Prompt cannot be empty.")

        response = (
            "Mock AI response:\n"
            "This response was generated by MockAIProvider.\n\n"
            f"Original prompt:\n{prompt}"
        )

        if max_tokens is not None:
            # A simple character-based limit for testing only.
            response = response[:max_tokens * 4]

        return response